class Solution {
public:
    vector<int> statisticalResult(vector<int>& a) {
        int n = a.size();
        vector<int> ans(n);
        for (int i = 0, left = 1; i < n; ++i) {
            ans[i] = left;
            left *= a[i];
        }
        for (int i = n - 1, right = 1; ~i; --i) {
            ans[i] *= right;
            right *= a[i];
        }
        return ans;
    }
};
